// Read every uploaded TXT file and combine them into one labeled payload.
// This is important: appointment, patient, doctor, and schedule data must be
// available together before matching IDs and checking availability.
const inputItems = $input.all();
const sections = [];
for (let i = 0; i < inputItems.length; i++) {
  const binaries = inputItems[i].binary || {};
  for (const key of Object.keys(binaries)) {
    const meta = binaries[key] || {};
    const fileName = meta.fileName || key;
    const buffer = await this.helpers.getBinaryDataBuffer(i, key);
    const contents = buffer.toString('utf8');
    sections.push(`===== FILE: ${fileName} =====\n${contents}`);
  }
}
if (!sections.length) {
  throw new Error('No uploaded text files were found. Upload the appointment, patient, doctor, and schedule TXT files.');
}
return [{ json: { combinedFiles: sections.join('\n\n') } }];

const outputs = $input.all();
const appointments = [], patients = [], doctors = [], schedules = [];
for (const item of outputs) {
  const out = item.json.output || item.json || {};
  if (Array.isArray(out.appointments)) appointments.push(...out.appointments);
  if (Array.isArray(out.patients)) patients.push(...out.patients);
  if (Array.isArray(out.doctors)) doctors.push(...out.doctors);
  if (Array.isArray(out.schedules)) schedules.push(...out.schedules);
}
const now = DateTime.now().setZone('Asia/Manila');
const parseDateTime = (date, time) => {
  const d = String(date ?? '').trim(), t = String(time ?? '').trim();
  if (!d || !t) return DateTime.invalid('Missing date/time');
  let dt = DateTime.fromFormat(`${d} ${t}`, 'yyyy-M-d h:mm a', { zone:'Asia/Manila', locale:'en-US' });
  if (!dt.isValid) dt = DateTime.fromFormat(`${d} ${t}`, 'yyyy-M-d H:mm', { zone:'Asia/Manila', locale:'en-US' });
  return dt;
};
const parseClock = value => {
  const s = String(value ?? '').trim();
  let dt = DateTime.fromFormat(s, 'h:mm a', { zone:'Asia/Manila', locale:'en-US' });
  if (!dt.isValid) dt = DateTime.fromFormat(s, 'H:mm', { zone:'Asia/Manila', locale:'en-US' });
  return dt;
};
const activeStatus = s => ['CONFIRMED','RESCHEDULED','BOOKED','PENDING'].includes(String(s ?? '').trim().toUpperCase());
const normalizedDay = d => String(d ?? '').trim().toUpperCase();
const result = [];
for (const a of appointments) {
  const patient = patients.find(p => String(p.patient_id ?? '').trim() === String(a.patient_id ?? '').trim());
  const doctor = doctors.find(d => String(d.doctor_id ?? '').trim() === String(a.doctor_id ?? '').trim());
  const rawDate = String(a.date ?? '').trim(), rawTime = String(a.time ?? '').trim();
  const dt = parseDateTime(rawDate, rawTime);
  let dateValid = false, validationReason = '';
  if (!rawDate || !rawTime) validationReason = 'Missing date or time.';
  else if (!dt.isValid) validationReason = 'Invalid date/time format or impossible calendar date/time.';
  else if (dt.toMillis() <= now.toMillis()) validationReason = 'Appointment date/time is not in the future (Asia/Manila).';
  else dateValid = true;

  const doctorName = doctor?.name || 'N/A';
  const specialization = doctor?.specialization || 'N/A';
  let availabilityValid = false, availabilityReason = '';
  let scheduleMatch = null;
  if (!dateValid) {
    availabilityReason = 'Availability was not checked because the appointment date/time is invalid.';
  } else if (!doctor) {
    availabilityReason = `Doctor ID ${a.doctor_id || '(missing)'} was not found in the doctor file.`;
  } else {
    const weekday = dt.toFormat('cccc').toUpperCase();
    scheduleMatch = schedules.find(s =>
      String(s.doctor_id ?? '').trim() === String(a.doctor_id ?? '').trim() &&
      normalizedDay(s.day_of_week) === weekday &&
      (s.available === true || String(s.available).trim().toLowerCase() === 'true')
    );
    if (!scheduleMatch) {
      availabilityReason = `Dr. ${doctorName} has no active schedule listed for ${weekday}.`;
    } else {
      const shiftStart = parseClock(scheduleMatch.start_time);
      const shiftEnd = parseClock(scheduleMatch.end_time);
      const requestedEnd = dt.plus({ hours: 1 });
      if (!shiftStart.isValid || !shiftEnd.isValid) {
        availabilityReason = 'The doctor schedule has an invalid start or end time.';
      } else {
        const startMinutes = dt.hour * 60 + dt.minute;
        const endMinutes = requestedEnd.hour * 60 + requestedEnd.minute;
        const shiftStartMinutes = shiftStart.hour * 60 + shiftStart.minute;
        const shiftEndMinutes = shiftEnd.hour * 60 + shiftEnd.minute;
        if (startMinutes < shiftStartMinutes || endMinutes > shiftEndMinutes) {
          availabilityReason = `Requested one-hour appointment is outside Dr. ${doctorName}'s listed hours (${scheduleMatch.start_time}–${scheduleMatch.end_time}).`;
        } else {
          const conflict = appointments.find(other => {
            if (String(other.clinic_id ?? '').trim() === String(a.clinic_id ?? '').trim()) return false;
            if (String(other.doctor_id ?? '').trim() !== String(a.doctor_id ?? '').trim()) return false;
            if (!activeStatus(other.status)) return false;
            const otherDt = parseDateTime(other.date, other.time);
            if (!otherDt.isValid || otherDt.toISODate() !== dt.toISODate()) return false;
            const otherEnd = otherDt.plus({ hours: 1 });
            return dt.toMillis() < otherEnd.toMillis() && requestedEnd.toMillis() > otherDt.toMillis();
          });
          if (conflict) {
            availabilityReason = `Dr. ${doctorName} already has an appointment overlapping this one-hour time slot (${conflict.date} ${conflict.time}, reference ${conflict.clinic_id}).`;
          } else {
            availabilityValid = true;
            availabilityReason = '';
          }
        }
      }
    }
  }
  const formattedDate = dt.isValid ? dt.toFormat('MMMM d, yyyy') : rawDate;
  const formattedTime = dt.isValid ? dt.toFormat('h:mm a') : rawTime;
  const startIso = dateValid ? dt.toISO() : null;
  const endIso = dateValid ? dt.plus({ hours: 1 }).toISO() : null;
  const appointmentDetails = `Appointment ID: ${a.clinic_id || 'N/A'}
Patient ID: ${a.patient_id || 'N/A'}
Doctor: ${doctorName}
Specialization: ${specialization}
Date: ${formattedDate}
Time: ${formattedTime}
Purpose: ${a.purpose || 'N/A'}
Status: ${a.status || 'N/A'}
Date validation: ${dateValid ? 'VALID' : 'INVALID'}${validationReason ? ' - ' + validationReason : ''}
Doctor availability: ${availabilityValid ? 'AVAILABLE' : 'UNAVAILABLE'}${availabilityReason ? ' - ' + availabilityReason : ''}
Clinic: ${a.clinic_id || 'N/A'}`;
  result.push({json:{
    clinic_id:a.clinic_id, patient_id:a.patient_id, doctor_id:a.doctor_id,
    date:a.date, time:a.time, purpose:a.purpose, status:a.status,
    date_valid:dateValid, date_validation_reason:validationReason,
    doctor_available:availabilityValid, availability_reason:availabilityReason,
    patient_name:patient?.name || a.patient_id || 'Patient',
    patient_email:patient?.email || '', doctor_name:doctorName, specialization,
    formatted_date:formattedDate, formatted_time:formattedTime,
    start_iso:startIso, end_iso:endIso, appointment_details:appointmentDetails
  }});
}
return result;

// Safely find the old calendar event for a RESCHEDULED appointment.
// A new appointment reference (for example APT-112) may differ from the old event's ID.
// Do not throw when no unique old event is found; the IF node will route around deletion.
const source = $('Collect Appointments').all().map(item => item.json ?? {});
const rescheduled = source.filter(item =>
  String(item.status ?? '').trim().toUpperCase() === 'RESCHEDULED'
);

if (rescheduled.length === 0) {
  throw new Error('No RESCHEDULED appointment found in Collect Appointments.');
}

// This workflow's current branch handles the first RESCHEDULED record in the uploaded file.
// (The appointment fixture supplied for this run contains one RESCHEDULED record.)
const appointmentData = rescheduled[0];
const appointmentId = String(appointmentData.clinic_id ?? '').trim();
const patientId = String(appointmentData.patient_id ?? '').trim();
const doctorId = String(appointmentData.doctor_id ?? '').trim();
const patientName = String(appointmentData.patient_name ?? '').trim();
const doctorName = String(appointmentData.doctor_name ?? '').trim();
const purpose = String(appointmentData.purpose ?? '').trim();

const events = $input.all().map(item => item.json ?? {}).filter(event => event.id || event.eventId);
const norm = value => String(value ?? '').trim().toLowerCase();

function fieldHas(text, labels, expectedValues) {
  const expected = new Set(expectedValues.map(norm).filter(Boolean));
  if (!expected.size) return false;
  return String(text ?? '').split(/\r?\n/).some(line => {
    const colon = line.indexOf(':');
    if (colon < 0) return false;
    const label = line.slice(0, colon).trim().toLowerCase();
    const value = norm(line.slice(colon + 1));
    return labels.includes(label) && expected.has(value);
  });
}

function matchesAppointmentId(event) {
  const description = String(event.description ?? '');
  return fieldHas(description, ['appointment id', 'appointment reference', 'reference'], [appointmentId]);
}

function matchesPatient(event) {
  const description = String(event.description ?? '');
  const summary = String(event.summary ?? '');
  return fieldHas(description,
      ['patient id', 'appointment patient id', 'patient'], [patientId]) ||
    fieldHas(description, ['patient name', 'patient'], [patientName]) ||
    (patientName && norm(summary).includes(norm(patientName)));
}

function matchesDoctor(event) {
  const description = String(event.description ?? '');
  return fieldHas(description, ['doctor id', 'doctor'], [doctorId, doctorName]);
}

function matchesPurpose(event) {
  const description = String(event.description ?? '');
  const summary = String(event.summary ?? '');
  return fieldHas(description, ['purpose', 'reason'], [purpose]) ||
    (purpose && norm(summary).includes(norm(purpose)));
}

let matchingEvent = events.find(matchesAppointmentId) ?? null;
let matchReason = '';

if (!matchingEvent && patientId && doctorId) {
  const candidates = events.filter(event => matchesPatient(event) && matchesDoctor(event));
  const purposeMatches = candidates.filter(matchesPurpose);

  if (purposeMatches.length === 1) {
    matchingEvent = purposeMatches[0];
  } else if (purposeMatches.length > 1) {
    matchReason = 'Multiple existing events match the patient, doctor, and purpose; no event was deleted to avoid removing the wrong appointment.';
  } else if (candidates.length === 1) {
    // Purpose may have changed during rescheduling; only use this fallback when unique.
    matchingEvent = candidates[0];
  } else if (candidates.length > 1) {
    matchReason = 'Multiple existing events match the patient and doctor; no event was deleted to avoid removing the wrong appointment.';
  }
}

const previousEventFound = Boolean(matchingEvent && (matchingEvent.id || matchingEvent.eventId));
if (!previousEventFound && !matchReason) {
  matchReason = events.length
    ? 'No existing calendar event could be uniquely matched to this patient and doctor.'
    : 'No existing calendar events were returned for the requested date window.';
}

return [{
  json: {
    eventId: previousEventFound ? (matchingEvent.id ?? matchingEvent.eventId) : '',
    previous_event_found: previousEventFound,
    previous_event_match_reason: matchReason,
    appointmentId,
    clinic_id: appointmentData.clinic_id,
    patient_id: appointmentData.patient_id,
    patient_name: appointmentData.patient_name,
    patient_email: appointmentData.patient_email,
    doctor_id: appointmentData.doctor_id,
    doctor_name: appointmentData.doctor_name,
    specialization: appointmentData.specialization,
    date: appointmentData.date,
    time: appointmentData.time,
    purpose: appointmentData.purpose,
    status: appointmentData.status,
    start_iso: appointmentData.start_iso,
    end_iso: appointmentData.end_iso
  }
}];

